import{_ as e,o as s,c as a,a2 as i}from"./chunks/framework.DZhUhjDB.js";const g=JSON.parse('{"title":"�‍� Security Analyst (Generalista)","description":"�‍� Security Analyst (Generalista)","frontmatter":{"title":"�‍� Security Analyst (Generalista)","description":"�‍� Security Analyst (Generalista)"},"headers":[],"relativePath":"roles/blue-team/security-analyst.md","filePath":"roles/blue-team/security-analyst.md","lastUpdated":1787529976000}'),r={name:"roles/blue-team/security-analyst.md"};function o(n,t,d,l,c,p){return s(),a("div",null,[...t[0]||(t[0]=[i(`<div align="center"><h1 id="🧑‍💻-security-analyst-generalista" tabindex="-1">🧑‍💻 Security Analyst (Generalista)</h1><p><strong>NIST NICE · Cybersecurity Analyst (broad)</strong></p><p><em>&quot;El generalista que conecta los puntos cuando nadie más los ve.&quot;</em></p><p><img src="https://img.shields.io/badge/tier%20salarial-C%2FB-blue" alt="Tier"> <img src="https://img.shields.io/badge/demanda-muy%20alta-brightgreen" alt="Demanda"> <img src="https://img.shields.io/badge/entry%20level-MUY%20amigable-success" alt="Entry"></p></div><hr><h2 id="📋-descripcion" tabindex="-1">📋 Descripción</h2><p>Rol <strong>generalista</strong> que toca múltiples áreas — alertas, vulnerabilidades, controles, evidencias, reportes. <strong>No es lo mismo que SOC Analyst</strong> (más reactivo a alertas) ni que Vuln Analyst (más patches). Es el &quot;Swiss Army Knife&quot; de seguridad en pymes y MSSPs, especialmente útil en orgs sin SOC formal.</p><p>Es <strong>el segundo título más común</strong> en LinkedIn de ciberseguridad. Suele ser el primer rol post-bootcamp / post-Security+. Desde aquí se especializa: hacia SOC, GRC, AppSec, IR o Cloud.</p><hr><h2 id="👤-roles-tipicos" tabindex="-1">👤 Roles típicos</h2><ul><li><strong>Security Analyst</strong> — generalista en pyme / MSSP</li><li><strong>Junior Cybersecurity Analyst</strong> — primer rol post-cert</li><li><strong>Information Security Analyst</strong> — más papelero (políticas + soporte audit)</li><li><strong>MSSP Analyst</strong> — multi-cliente, multi-tarea</li><li><strong>IT Security Analyst</strong> — sysadmin con sombrero seguridad</li></ul><hr><h2 id="🛠️-stack-y-herramientas" tabindex="-1">🛠️ Stack y herramientas</h2><table tabindex="0"><thead><tr><th>Categoría</th><th>Herramientas</th></tr></thead><tbody><tr><td><strong>SIEM básico</strong></td><td>Wazuh · Microsoft Sentinel · Elastic SIEM (free) · Sumo Logic</td></tr><tr><td><strong>EDR</strong></td><td>Microsoft Defender for Endpoint · CrowdStrike (operativo)</td></tr><tr><td><strong>VM scanners</strong></td><td>Tenable Nessus Essentials · OpenVAS · Nuclei</td></tr><tr><td><strong>GRC light</strong></td><td>Excel · Google Sheets · Notion · Confluence</td></tr><tr><td><strong>Threat Intel</strong></td><td>AlienVault OTX · MISP · VirusTotal</td></tr><tr><td><strong>Productividad</strong></td><td>Jira · ServiceNow · Trello · Loom para reportes</td></tr><tr><td><strong>Análisis</strong></td><td>Wireshark básico · Sysmon · Process Hacker</td></tr><tr><td><strong>Documentación</strong></td><td>Markdown · diagramas Mermaid · ADRs</td></tr></tbody></table><hr><h2 id="🎓-certificaciones-recomendadas" tabindex="-1">🎓 Certificaciones recomendadas</h2><table tabindex="0"><thead><tr><th>Nivel</th><th>Certificación</th><th>Vendor</th><th>Costo (USD)</th><th>Notas</th></tr></thead><tbody><tr><td>Entry</td><td>CompTIA Security+</td><td>CompTIA</td><td>~$400</td><td><strong>El must</strong></td></tr><tr><td>Entry</td><td>Microsoft SC-900</td><td>Microsoft</td><td>~$100</td><td>Conceptos cloud security</td></tr><tr><td>Entry</td><td>Google Cybersecurity Certificate</td><td>Coursera</td><td>~$50/mes</td><td>6 cursos, MUY accesible</td></tr><tr><td>Entry</td><td>ISC2 CC (Certified in Cybersecurity)</td><td>(ISC)²</td><td>~$200</td><td>Free in some pilots</td></tr><tr><td>Mid</td><td>CompTIA CySA+</td><td>CompTIA</td><td>~$400</td><td>Si vas hacia SOC</td></tr><tr><td>Mid</td><td>SC-200</td><td>Microsoft</td><td>~$165</td><td>Si tu stack es MS</td></tr></tbody></table><hr><h2 id="🗺️-roadmap-12-meses" tabindex="-1">🗺️ Roadmap (12 meses)</h2><h3 id="fase-1-—-fundamentos-0-3-meses" tabindex="-1">Fase 1 — Fundamentos (0-3 meses)</h3><ul><li>[ ] CompTIA Security+ aprobado</li><li>[ ] Wazuh + 2 endpoints generando alertas</li><li>[ ] OWASP Top 10 + MITRE ATT&amp;CK leídos</li><li>[ ] LinkedIn optimizado + 5 writeups TryHackMe en GitHub</li></ul><h3 id="fase-2-—-especializacion-3-6-meses" tabindex="-1">Fase 2 — Especialización (3-6 meses)</h3><ul><li>[ ] Decidir vertical: SOC | GRC | AppSec | Cloud | IR</li><li>[ ] Cert vertical correspondiente (BTL1, CySA+, SC-200, AWS Practitioner)</li><li>[ ] LetsDefend SOC path o equivalente</li><li>[ ] Networking: 1 evento mensual / Discord servers de ciberseguridad LATAM</li></ul><h3 id="fase-3-—-profesional-6-12-meses" tabindex="-1">Fase 3 — Profesional (6-12 meses)</h3><ul><li>[ ] Conseguir el primer rol especializado (transición desde generalista)</li><li>[ ] Cert mid del vertical elegido</li><li>[ ] Portafolio público (blog / GitHub / talks)</li><li>[ ] Identificar mentor/a en el vertical</li></ul><hr><h2 id="💰-salarios-en-colombia-usd-mes" tabindex="-1">💰 Salarios en Colombia (USD/mes)</h2><table tabindex="0"><thead><tr><th>Nivel</th><th>Local 🇨🇴</th><th>Remoto 🌎</th><th>Notas</th></tr></thead><tbody><tr><td>Junior (0-2 años)</td><td>$500 - $1,100</td><td>$1,000 - $2,000</td><td>Punto de entrada típico</td></tr><tr><td>Mid (2-5 años)</td><td>$1,200 - $2,500</td><td>$2,200 - $4,000</td><td>Si no especializa, queda capped</td></tr><tr><td>Senior (5+ años)</td><td>$2,800 - $5,500</td><td>$4,500 - $8,000</td><td>Solo si se especializa</td></tr></tbody></table><blockquote><p><strong>⚠️ Aviso honesto:</strong> &quot;Security Analyst&quot; sin especialización <strong>se queda en mid-tier salarial</strong>. Es excelente punto de entrada — pero define tu vertical en menos de 18 meses o el techo se siente.</p></blockquote><hr><h2 id="🔗-conexion-con-otras-ramas" tabindex="-1">🔗 Conexión con otras ramas</h2><ul><li><strong><code>analista-soc</code></strong> → vertical más común si te gusta operación</li><li><strong><code>grc-compliance</code></strong> → vertical si te gusta políticas y auditoría</li><li><strong><code>vulnerability-manager</code></strong> → vertical si te gusta patching/priorización</li><li><strong><code>seguridad-aplicaciones</code></strong> → vertical si vienes de dev</li><li><strong><code>seguridad-nube</code></strong> → vertical con mejor salario remoto</li></ul><hr><h2 id="📂-estructura" tabindex="-1">📂 Estructura</h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>security-analyst/</span></span>
<span class="line"><span>├── herramientas/    # Wazuh setup, Sentinel queries básicas, plantillas</span></span>
<span class="line"><span>├── recursos/        # OWASP, ATT&amp;CK quick-refs, glosario</span></span>
<span class="line"><span>├── laboratorios/    # TryHackMe paths, LetsDefend writeups</span></span>
<span class="line"><span>└── casos-uso/       # Tareas reales: phishing triage, vuln triage, audit</span></span></code></pre></div><hr><div align="center"><p><strong><a href="./../README">⬅ Volver a Ciberseguridad</a></strong></p></div>`,34)])])}const m=e(r,[["render",o]]);export{g as __pageData,m as default};
